NewRequestScreen.btnSubmit.OnSelect:
Patch(
    'Onboarding Requests',
    Defaults('Onboarding Requests'),
    {
        Title: Trim(txtGivenName.Text) & " " & Trim(txtSurname.Text),
        'Given name': Trim(txtGivenName.Text),
        Surname: Trim(txtSurname.Text),
        Department: {Value: ddDepartment.Selected.Value},
        'Job title': Trim(txtJobTitle.Text),
        'Hiring manager': cmbManager.Selected.Mail,
        'Start date': dpStart.SelectedDate,
        'Usage location': "PT",
        Status: {Value: "Submitted"}
    }
);
Notify("Sent to " & cmbManager.Selected.DisplayName & " for approval.", NotificationType.Success);
Reset(txtGivenName); Reset(txtSurname); Reset(txtJobTitle);
Navigate(MyRequestsScreen, ScreenTransition.None)
